// Kontrollerar F9 + k-009: viewport i index.html, länk till lugnt-lage.css och att CSS:en har rätt regler.
// AI-skapat (B-051). Generated by AI, Directed by MS.
import fs from 'fs';
const css = fs.readFileSync('public/css/lugnt-lage.css', 'utf8');
const html = fs.readFileSync('public/index.html', 'utf8');
const krav = {
  reducedMotion: css.includes('@media (prefers-reduced-motion: reduce)'),
  ingenAnimation: /animation-duration:\s*0\.01ms/.test(css),
  pagarUtanPuls: css.includes('.vp-card.pagar'),
  mediaMaxBredd: css.includes('max-width: 100%'),
  aiMarkt: css.includes('Generated by AI, Directed by MS'),
  viewport: /<meta[^>]+name="viewport"[^>]+width=device-width/.test(html),
  lankad: html.includes('/css/lugnt-lage.css'),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
